  const label=node('label','本任务事件归并阈值'),input=node('input',null,{type:'number',min:'.01',max:'1',step:'.01',value:String(d.method.threshold),'aria-label':'本任务事件归并阈值'});label.append(input);
  const advanced=node('details');advanced.append(node('summary','调整归并阈值（将重新分析）'),label,node('p',`达到 ${d.method.threshold} 自动归并，边界候选交模型判定。`,{class:'help'}),button('应用阈值并重新分析',async()=>{if(!Number.isFinite(Number(input.value))||Number(input.value)<=0||Number(input.value)>1)throw Error('阈值需大于0且不超过1。');await flushReviewDraft(d);await post(`/api/tasks/${d.id}/event-settings`,{expected_revision:d.revision,threshold:Number(input.value)});$('#reviewDialog').close();shownRevision=null;toast('已保存当前草稿，按新阈值重新分析后需要重新审核。');await refresh()}));section.append(advanced);
