function renderAmbiguities(body,d){
 const gate=reviewGate(d),all=d.merge_ambiguities||[],pendingIds=new Set([...gate.pending,...gate.conflicts].map(c=>c.id));
 if(d.human_relationship_history?.length){const history=node('details');history.append(node('summary',`已保留的人工判断（${d.human_relationship_history.length}项）`));for(const c of d.human_relationship_history)history.append(node('p',`${d.records[c.source_id]?.title||'事件甲'} ↔ ${d.records[c.target_id]?.title||'事件乙'}：${c.decision==='same'?'同一事件':'不同事件'}`));body.append(history)}
 body.append(node('p','这里逐对比较两个当前事件组，展示各组的代表内容；一个组可以包含多条记录。连续确认甲与乙、乙与丙为同一事件后，会归为一个更大的组，并不限制为两个事件。',{class:'help'}));const controls=node('div',null,{class:'review-tabs'});controls.append(node('strong',`已判断 ${all.length-gate.pending.length}/${all.length} 项`),button(d.pendingOnly?'查看全部关系':'仅看未完成关系',()=>{d.pendingOnly=!d.pendingOnly;renderData()}));body.append(controls);
 const cases=d.pendingOnly?all.filter(c=>pendingIds.has(c.id)):all;
 if(!cases.length){body.append(node('p',all.length?'所有事件关系已处理。若分组有变化，请使用下方“应用人工判断并进入下一步”继续。':'没有需要人工兜底的事件关系。',{class:'notice'}));return}
 for(const c of cases){const card=node('section',null,{class:'member-card relationship-case','data-case-id':c.id});card.append(node('h3','判断是否同一事件'),node('p','模型不确定的原因：'+c.reason));for(const [label,items,rid] of [['事件组甲',c.source_evidence,c.source_id],['事件组乙',c.target_evidence,c.target_id]]){const group=d.groups.find(g=>g.member_ids.includes(rid));card.append(node('p',`${label}当前包含 ${group?.member_ids.length||1} 条记录；以下为代表内容。`,{class:'help'}));for(const r of items)card.append(node('strong',label+'：'+r.title),node('p',r.summary))}
  if(d.mergeDecisions[c.id])card.append(node('p','已记录判断：'+(d.mergeDecisions[c.id]==='same'?'同一事件':'不同事件')));
  if(gate.conflicts.some(item=>item.id===c.id))card.append(node('p','当前分组与此前判断冲突，请核对事件成员或修改判断。',{class:'notice'}));
  if(!d.frozen&&!d.analysis_pending){card.append(button('判为同一事件',async()=>{const a=d.groups.find(g=>g.member_ids.includes(c.source_id)),b=d.groups.find(g=>g.member_ids.includes(c.target_id));if(!a||!b)throw Error('事件成员已更新，请重新打开审核页。');if(a!==b){b.member_ids.push(...a.member_ids);a.member_ids=[];normalizeGroups(d);d.groupsDirty=true}d.mergeDecisions[c.id]='same';$('#dialogNotice').textContent='';await finishRelationshipChoice(d)}),button('判为不同事件',async()=>{if(d.groups.find(g=>g.member_ids.includes(c.source_id))===d.groups.find(g=>g.member_ids.includes(c.target_id)))throw Error('两条记录当前已在同一事件中，请先到事件页拆分后再判断。');d.mergeDecisions[c.id]='different';$('#dialogNotice').textContent='';await finishRelationshipChoice(d)}))}body.append(card)
 }
}

function renderTop10(body,d){
 body.append(node('p','入榜：负面且已预警的记录，先归并为事件；排序：同一事件内符合条件的记录条数降序。一个事件只展示一条15—35字的严肃、简明梗概。',{class:'help'}));
 if(d.groupsDirty)body.append(node('p','事件分组已调整，以下梗概属于调整前版本，请先点击“应用人工分组并重算数据（不调用模型）”。',{class:'notice'}));
 const rows=d.top10||[];
 if(!rows.length){body.append(node('p','尚无已生成的 TOP10。模型处理完成后再查看。'));return}
 const table=node('table',null,{class:'count-table top10-table'}),head=node('tr');['排名','事件梗概','负面且已预警条数'].forEach(text=>head.append(node('th',text)));table.append(head);
 for(const row of rows){const patch=d.briefPatches[row.fingerprint],summary=patch?.summary||row.summary,tr=node('tr');tr.append(node('td',String(row.rank)),node('td',summary||(row.status==='uncertain'?'〔模型证据不足，待人工补充梗概〕':'〔梗概待处理〕')),node('td',String(row.negative_warning_count)));table.append(tr)}body.append(table);
 for(const row of rows){const details=node('details');details.append(node('summary',`第 ${row.rank} 名 · 查看来源${row.status!=='complete'?'及补充梗概':''}`));if(row.reason)details.append(node('p',row.reason,{class:'help'}));const text=node('textarea',null,{rows:'3',minlength:'15',maxlength:'35','aria-label':`第 ${row.rank} 名事件梗概`});text.value=d.briefPatches[row.fingerprint]?.summary||row.summary;text.disabled=d.frozen||d.analysis_pending;const counter=node('p',null,{class:'help'});const countText=()=>{const n=[...text.value.trim()].length;counter.textContent=`${n} / 15—35字（含标点）`;counter.style.color=n>=15&&n<=35?'':'#9b2734'};text.oninput=countText;countText();details.append(text,counter);for(const id of row.negative_ids.slice(0,4)){const record=d.records[id];details.append(node('strong',record.title),node('p',record.summary),node('p',record.published,{class:'help'}));if(/^https?:\/\//i.test(record.url))details.append(node('a','查看原始内容',{href:record.url,target:'_blank',rel:'noopener noreferrer'}))}if(!d.frozen&&!d.analysis_pending)details.append(button('应用这条事件梗概',()=>{if([...text.value.trim()].length<15||[...text.value.trim()].length>35)throw Error('事件梗概必须为15—35字。');d.briefPatches[row.fingerprint]={status:'complete',summary:text.value.trim(),source_refs:row.negative_ids.slice(0,4)};renderData()}));body.append(details)}
}

